// The spray reference every spray comparison and chart reads, built from the in-game patterns in
// recoil.ts (generated by tools/recoil.ts from the demos' own shot records). Per automatic gun:
// - cycle and mag: the game's cycle time and magazine, which cut shots into sprays (aim.ts);
// - kick: the in-game spray pattern, where each bullet goes relative to bullet 1 with no compensation;
// - ideal: the mouse movement that keeps every bullet on bullet 1's point (minus kick);
// - path: per bullet [idealPitch, idealYaw, proPitchQ25, proPitchQ75, proYawQ25, proYawQ75], the ideal
//   pull with the pros' middle half of view movement around it; where pro sprays thin out, the band
//   collapses onto the ideal pull (no band drawn).
// All in degrees, pitch positive down, index 0 is bullet 1. A gun without enough demo shots has an
// empty kick, ideal and path: its sprays are still kept and shown, but compared with nothing.
import { RECOIL as PATTERNS } from "./recoil";

export interface RecoilRef {
  cycle: number;
  mag: number;
  kick: readonly (readonly [number, number])[];
  ideal: readonly (readonly [number, number])[];
  path: readonly (readonly number[])[];
}

export const RECOIL: Record<string, RecoilRef> = Object.fromEntries(Object.entries(PATTERNS).map(([w, p]) => [w, {
  cycle: p.cycle, mag: p.mag, kick: p.kick, ideal: p.ideal,
  path: p.ideal.map(([ip, iy], j) => {
    const pro = p.pro[j];
    return pro ? [ip, iy, pro[2], pro[3], pro[4], pro[5]] : [ip, iy, ip, ip, iy, iy];
  }),
}]));
